window.__votdWeek && window.__votdWeek({"week":"2029-09-03","reading":"Doctrine and Covenants 94–97","days":[{"d":"2029-09-03","ref":"D&C 94:2","b":"D&C","c":94,"v":2,"he":"וְהִנֵּה יֵעָשֶׂה כַּתַּבְנִית אֲשֶׁר נָתַתִּי לָכֶם׃","en":"And behold, it must be done according to the pattern which I have given unto you."},{"d":"2029-09-04","ref":"D&C 94:8","b":"D&C","c":94,"v":8,"he":"וְלֹא תַנִּיחוּ דָבָר טָמֵא לָבוֹא בוֹ וּכְבוֹדִי יִהְיֶה שָׁם וּפָנַי יִהְיוּ שָׁם׃","en":"And ye shall not suffer any unclean thing to come in unto it; and my glory shall be there, and my presence shall be there."},{"d":"2029-09-05","ref":"D&C 95:1","b":"D&C","c":95,"v":1,"he":"אָמֵן כֹּה אָמַר יְהוָה אֲלֵיכֶם אֲשֶׁר אֲנִי אֹהֵב וַאֲשֶׁר אֲנִי אֹהֵב אֲנִי גַם מְיַסֵּר לְמַעַן יִסָּלְחוּ חַטֹּאתֵיהֶם כִּי בַמּוּסָר אֲנִי מֵכִין דֶּרֶךְ לְהַצָּלָתָם מִכׇּל־נִסָּיוֹן וָאֹהַב אֶתְכֶם׃","en":"Verily, thus saith the Lord unto you whom I love, and whom I love I also chasten that their sins may be forgiven, for with the chastisement I prepare a way for their deliverance in all things out of temptation, and I have loved you—"},{"d":"2029-09-06","ref":"D&C 95:12","b":"D&C","c":95,"v":12,"he":"אִם לֹא תִשְׁמְרוּ מִצְוֹתַי לֹא אַהֲבַת הָאָב תַּעֲמֹד עִמָּכֶם לָכֵן תֵּלְכוּ בַּחֹשֶׁךְ׃","en":"If you keep not my commandments, the love of the Father shall not continue with you, therefore you shall walk in darkness."},{"d":"2029-09-07","ref":"D&C 96:2","b":"D&C","c":96,"v":2,"he":"לָכֵן יִפְקֹד עַבְדִּי נְיוּאֶל ק. וִיטְנִי אֶת־הַמָּקוֹם הַנִּקְרָא בֵינֵיכֶם אֲשֶׁר עָלָיו חָפַצְתִּי לִבְנוֹת אֶת־בֵּיתִי הַקָּדוֹשׁ׃","en":"Therefore, let my servant Newel K. Whitney take charge of the place which is named among you, upon which I design to build mine holy house."},{"d":"2029-09-08","ref":"D&C 97:7","b":"D&C","c":97,"v":7,"he":"הַגַּרְזֶן הוּשַׂם עַל־שֹׁרֶשׁ הָעֵצִים וְכׇל־עֵץ אֲשֶׁר־אֵינֶנּוּ עֹשֶׂה פְּרִי טוֹב יִכָּרֵת וְהֻשְׁלַךְ בָּאֵשׁ אֲנִי יְהוָה דִּבַּרְתִּי׃","en":"The ax is laid at the root of the trees; and every tree that bringeth not forth good fruit shall be hewn down and cast into the fire. I, the Lord, have spoken it."},{"d":"2029-09-09","ref":"D&C 97:26","b":"D&C","c":97,"v":26,"he":"וְאִם לֹא תִשְׁמֹר לַעֲשׂוֹת כׇּל־אֲשֶׁר צִוִּיתִיהָ אֶפְקֹד עָלֶיהָ כְּכׇל־מַעֲשֶׂיהָ בְּצָרָה קָשָׁה בְּדֶבֶר בְּמַגֵּפָה בְּחֶרֶב בְּנָקָם בְּאֵשׁ אֹכֶלֶת׃","en":"But if she observe not to do whatsoever I have commanded her, I will visit her according to all her works, with sore affliction, with pestilence, with plague, with sword, with vengeance, with devouring fire."}]});
